-- evt:thing:pear_basket
RegisterEvent(142, "The pear hut", function()
    if not (not (IsPlayerBitSet(PlayerBit(11320)))) then
        evt.StatusText("You have had your share. The rest look far less tempting now.", 6)
        return
    end
    AddValue(BaseMight, 2)
    SetValue(Weak, 1)
    SetPlayerBit(PlayerBit(11320))
    evt.StatusText("A basket of pears on the sill of a whitewashed hut. \"The pear of plenty.\" You feel stronger, and then very tired. (+2 Might (permanent), and Weak)", 6)
end, "The pear hut")

-- evt:thing:fig_basket
RegisterEvent(143, "The fig hut", function()
    if not (not (IsPlayerBitSet(PlayerBit(11321)))) then
        evt.StatusText("You have had your share. The rest look far less tempting now.", 6)
        return
    end
    AddValue(BaseIntellect, 2)
    SetValue(Insane, 1)
    SetPlayerBit(PlayerBit(11321))
    evt.StatusText("Figs in a bowl by the door of a mossy log hut. \"The fig of foresight.\" You see everything. Everything sees you. (+2 Intellect (permanent), and Insane)", 6)
end, "The fig hut")

