    Xeen.markToday("d3_wayside_shrine") evt.ForPlayer(Players.All)
    AddValue(FireResistanceBonus, 10)
    evt.StatusText("A faded sun painted on the stone, still warm. (+10 Fire resistance until you rest)", 6)
end, "Wayside shrine of the desert sun")

